J: {
  // ===== mise en train =====
  statues: {n: 'Les statues musicales', k: 'opp', s: 'danse:danse:groupes', d: 'On danse librement sur la musique ; quand elle s\'arrête, on se fige en statue. Qui bouge devient « juge » et aide à repérer les autres. Le prof impose parfois la statue : « une statue triste », « à 3 appuis », « au niveau bas ».'},
  prenom: {n: 'Mon prénom dansé', k: 'coop', s: 'danse:danse:cercle', f: 'g8', d: 'En cercle, chacun danse son prénom (un geste par syllabe), puis tout le cercle le répète. On fait le tour du cercle, de plus en plus vite. Puis on enchaîne 3 prénoms d\'affilée !'},
  chef: {n: 'Qui est le chef ?', k: 'opp', s: 'danse:danse:cercle', f: 'g8', d: 'Un enquêteur sort du cercle. On choisit en silence un chef d\'orchestre qui change de geste toutes les 8 temps ; tout le cercle le copie. L\'enquêteur revient et a 3 essais pour trouver le chef.'},
  magneto: {n: 'Le magnétoscope', k: 'coop', s: 'danse:danse:groupes', d: 'On danse ou on marche en rythme ; le prof (puis un élève) crie « pause » (figé), « ralenti », « avance rapide », « retour arrière » (on refait à l\'envers), « lecture ». Le dernier à réagir devient la télécommande.'},
  miroir: {n: 'Le miroir', k: 'coop', s: 'danse:danse:miroir', f: 'p', d: 'Par deux face à face : l\'un mène lentement, l\'autre copie en même temps comme un miroir. Au signal, on change de meneur sans s\'arrêter. Le but : qu\'un spectateur ne sache plus qui mène.'},
  huit: {n: 'Les 8 temps', k: 'coop', s: 'danse:danse:lignes', d: 'On marche en comptant à voix haute « 1 à 8 » sur le temps de la musique ; sur le 8, on change de direction (ou on frappe dans les mains, on saute, on se baisse…). Puis on ne compte plus que dans sa tête.'},
  // ===== corps de leçon =====
  verbes: {n: 'Les cartes-verbes', k: 'coop', s: 'danse:danse:groupes', f: 'g4', d: 'Chaque groupe tire 4 cartes-verbes (tourner, sauter, glisser, tomber, pousser, s\'enrouler, s\'étirer, trembler…). Il invente un geste par verbe sur 8 temps, puis les enchaîne : 4 × 8 temps. On montre aux autres, qui devinent les verbes.'},
  telephone: {n: 'Le téléphone dansé', k: 'fp', s: 'danse:danse:lignes', f: 'g6', d: 'En file, dos au premier. Le premier invente une phrase de 8 temps, la montre au 2e seulement ; le 2e la montre au 3e… Le dernier la montre à tout le monde avec le premier : qu\'est-ce qui a changé ? Fous rires garantis.'},
  accumulation: {n: 'L\'accumulation', k: 'coop', s: 'danse:danse:cercle', f: 'g5', d: 'En cercle : le 1er fait un geste sur 8 temps ; tous le refont ; le 2e en ajoute un : on refait les 2 ; le 3e ajoute… jusqu\'à une phrase de 5 gestes que tout le groupe danse ensemble.'},
  canon: {n: 'L\'unisson et le canon', k: 'coop', s: 'danse:danse:canon', f: 'g4', d: 'Le groupe danse une phrase de 4 × 8 temps ensemble (unisson), puis en canon : chacun part 2 temps (ou 8 temps) après l\'autre. Puis en cascade (on part l\'un après l\'autre en vague). Le public dit lequel est le plus beau.'},
  question: {n: 'Question-réponse', k: 'coop', s: 'danse:danse:miroir', f: 'p', d: 'Par deux : A « pose une question » (8 temps de danse), B « répond » (8 temps qui reprennent un geste de A et le transforment). On enchaîne 4 questions-réponses, comme une conversation.'},
  qualites: {n: 'La météo du geste', k: 'coop', s: 'danse:danse:groupes', f: 'g4', d: 'Le même geste est dansé selon la météo annoncée : « soleil » (léger, fluide), « orage » (fort, saccadé), « brouillard » (lent), « tornade » (rapide, en tournant), « neige » (doux, vers le bas).'},
  ligne: {n: 'La danse en ligne', k: 'coop', s: 'danse:danse:lignes', d: 'Toute la classe en lignes. Le prof (ou un élève) apprend une danse en ligne de 32 temps (4 × 8) : pas de côté, vigne, avancer, reculer, quart de tour. On la répète jusqu\'à pouvoir la danser sans le meneur.'},
  cypher: {n: 'Le cypher', k: 'fp', s: 'danse:danse:cercle', f: 'g8', d: 'En cercle, on fait le bounce (rebond des genoux) sur la musique. À tour de rôle, un danseur entre au centre pour 8 à 16 temps, puis tape la main du suivant. Règle d\'or : on encourage, on ne se moque jamais.'},
  battle: {n: 'La battle', k: 'opp', s: 'danse:danse:groupes', f: 'e2', d: 'Deux équipes face à face. Chacune envoie un danseur (ou un duo) pour un passage de 16 temps ; l\'autre répond. Trois juges lèvent la main vers l\'équipe qui a le plus d\'énergie, d\'originalité et de respect. On se salue avant et après.'},
  rock: {n: 'Le rock des couples', k: 'coop', s: 'danse:danse:miroir', f: 'p', d: 'Par deux, une main tenue : pas de base du rock (« 1-2, 3-4, 5-6 » : deux pas sur place, puis un pas en arrière et revient). Toutes les 30 s, le prof crie « on change ! » et chacun va vers un nouveau partenaire.'},
  defile: {n: 'Le défilé', k: 'fp', s: 'danse:danse:lignes', f: 'g4', d: 'Sur un couloir de 10 m, chaque groupe défile sur la musique avec une démarche imposée (robot, pingouin, super-héros, vieux, ralenti…), puis s\'arrête au bout en « photo de groupe ». Le public applaudit la plus originale.'},
  spectacle: {n: 'La scène ouverte', k: 'fp', s: 'danse:danse:groupes', f: 'g4', d: 'Chaque groupe présente sa danse sur {scene}. Le public est assis, en silence ; après chaque passage, il dit « une étoile » (ce qui est réussi) et « un vœu » (un conseil). On applaudit chaque groupe.'},
  // ===== retour au calme =====
  bilan: {n: 'La révérence', k: 'fp', s: 'etirements', d: 'Étirements lents sur une musique douce. Chacun dit le nom d\'un danseur qui l\'a impressionné et pourquoi. Puis toute la classe fait une grande révérence ensemble.'},
  vague: {n: 'La vague', k: 'coop', s: 'danse:danse:cercle', d: 'En cercle, très lentement, une « vague » de mouvement passe d\'élève en élève : chacun la reçoit, la transforme un peu et la passe. On finit assis, yeux fermés, à respirer sur la musique.'}
},
